import{_ as s,H as a,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"33 | 告警：如何搭建基于HTTP状态告警？","description":"","frontmatter":{},"headers":[{"level":2,"title":"选择告警指标","slug":"选择告警指标","link":"#选择告警指标","children":[]},{"level":2,"title":"配置告警策略","slug":"配置告警策略","link":"#配置告警策略","children":[{"level":3,"title":"检查 PrometheusRule 是否生效","slug":"检查-prometheusrule-是否生效","link":"#检查-prometheusrule-是否生效","children":[]}]},{"level":2,"title":"配置通知","slug":"配置通知","link":"#配置通知","children":[{"level":3,"title":"获取邮箱 SMTP 密码","slug":"获取邮箱-smtp-密码","link":"#获取邮箱-smtp-密码","children":[]},{"level":3,"title":"配置 Prometheus 发信邮箱","slug":"配置-prometheus-发信邮箱","link":"#配置-prometheus-发信邮箱","children":[]}]},{"level":2,"title":"触发告警","slug":"触发告警","link":"#触发告警","children":[]},{"level":2,"title":"CPU 使用率告警","slug":"cpu-使用率告警","link":"#cpu-使用率告警","children":[{"level":3,"title":"其他告警策略集合","slug":"其他告警策略集合","link":"#其他告警策略集合","children":[]}]},{"level":2,"title":"其他通知方式","slug":"其他通知方式","link":"#其他通知方式","children":[{"level":3,"title":"安装 PrometheusAlert","slug":"安装-prometheusalert","link":"#安装-prometheusalert","children":[]},{"level":3,"title":"配置 PrometheusAlert","slug":"配置-prometheusalert","link":"#配置-prometheusalert","children":[]},{"level":3,"title":"创建飞书机器人","slug":"创建飞书机器人","link":"#创建飞书机器人","children":[]},{"level":3,"title":"配置 Alertmanager","slug":"配置-alertmanager","link":"#配置-alertmanager","children":[]},{"level":3,"title":"触发告警","slug":"触发告警-1","link":"#触发告警-1","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生架构与GitOps实战/33｜告警：如何搭建基于HTTP状态告警？.md","filePath":"云原生架构与GitOps实战/33｜告警：如何搭建基于HTTP状态告警？.md","lastUpdated":1795538134000}'),p={name:"云原生架构与GitOps实战/33｜告警：如何搭建基于HTTP状态告警？.md"};function i(l,e,r,o,h,E){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_33-告警-如何搭建基于http状态告警" tabindex="-1">33 | 告警：如何搭建基于HTTP状态告警？ <a class="header-anchor" href="#_33-告警-如何搭建基于http状态告警" aria-label="Permalink to &quot;33 | 告警：如何搭建基于HTTP状态告警？&quot;">​</a></h1><p>你好，我是王炜。</p><p>上一节课，我们学习了如何借助 Ingress-Nginx Dashboard 快速搭建业务 HTTP 状态监控。它内置了多项 HTTP 请求指标，例如 TPS、请求成功率、P99 延迟等，这些指标对于我们掌握业务整体的可用性有非常大的帮助。</p><p>不过，在生产环境下，人工实时观察这些指标是不现实的，我们需要有一种能够自动发现异常指标的机制，它能在发现异常时发出通知。</p><p>这种机制也就是我们常说的告警。</p><p>这节课，我会继续深入可观测性，以 HTTP 请求成功率为例，带你从零搭建该指标的告警策略，并在这个过程中进一步讲解告警策略的配置方法，让你掌握给任意指标配置告警策略的能力。</p><p>在开始今天的学习之前，你需要按照第 32 讲的内容部署示例应用，并配置好 Prometheus和 Ingress-Nginx Dashboard。</p><h2 id="选择告警指标" tabindex="-1">选择告警指标 <a class="header-anchor" href="#选择告警指标" aria-label="Permalink to &quot;选择告警指标&quot;">​</a></h2><p>对于初学者来说，上手编写一段 PromQL 并不容易，为了降低实战门槛，我们直接从Dashboard 中选择已有的指标配置告警策略。</p><p>首先，对 Grafana Service 进行端口转发。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl port-forward --namespace prometheus service/prometheus-grafana 3000:80</span></span></code></pre></div><p>然后，使用浏览器访问 <a href="http://127.0.0.1:3000" target="_blank" rel="noreferrer">http://127.0.0.1:3000</a> 打开&quot;&gt;<a href="http://127.0.0.1:3000" target="_blank" rel="noreferrer">http://127.0.0.1:3000</a>，使用账号密码admin/prom-operator 登录，点击左侧的 Dashboards 界面，搜索 “nginx” 并进入 Ingress-Nginx Dashboard，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/1.png" alt=""></a></p><p>进入 Ingress-Nginx Dashboard 之后，会看到界面中展示了丰富的 HTTP 请求指标。在生产环境下，我们一般会非常关注业务 HTTP 请求的总体成功情况，所以，这里我们选择反映接口的请求成功率的 Controller Success Rate 指标，并为它配置告警策略。</p><p>选择好指标后，接下来我们需要获取该指标的 PromQL 语句进一步配置告警策略。</p><p>点击 Controller Success Rate 指标的标题展开操作菜单，并选择&quot;Inspect&quot;-&gt;&quot;Query&quot;查看指标PromQL 语句。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/2.png" alt=""></a></p><p>在弹出的界面中，Expr 字段实际上就是这个指标的查询语句。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/3.png" alt=""></a></p><p>这条 PromQL 查询语句相对比较复杂，如果你现在还不能理解也没关系，我们现阶段只需要知道它反映了 HTTP 接口的总体可用性就可以了。接下来，我们将 Expr 字段的内容复制下来，方便在配置告警策略时使用。</p><h2 id="配置告警策略" tabindex="-1">配置告警策略 <a class="header-anchor" href="#配置告警策略" aria-label="Permalink to &quot;配置告警策略&quot;">​</a></h2><p>接下来，我们开始为 HTTP 请求成功率指标配置告警策略。</p><p>要配置告警策略，你需要创建 PrometheusRule CRD 对象，将下面的内容保存为 rule.yaml 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: monitoring.coreos.com/v1</span></span>
<span class="line"><span>kind: PrometheusRule</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span>   release: prometheus</span></span>
<span class="line"><span> name: http-success-rate</span></span>
<span class="line"><span> namespace: prometheus</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> groups:</span></span>
<span class="line"><span> - name: nginx.http.rate</span></span>
<span class="line"><span>   rules:</span></span>
<span class="line"><span>   - expr: |</span></span>
<span class="line"><span>       sum(rate(nginx_ingress_controller_requests{controller_pod=~&quot;.*&quot;,controlle</span></span>
<span class="line"><span>     for: 1m</span></span>
<span class="line"><span>     alert: HTTPSuccessRateDown</span></span>
<span class="line"><span>     annotations:</span></span>
<span class="line"><span>       summary: &quot;HTTP 请求成功率小于 90%&quot;</span></span>
<span class="line"><span>       description: &quot;HTTP 请求成功率小于 90%，请及时处理&quot;</span></span></code></pre></div><p>在这段内容里，我们重点关注 labels、expr、for 和 annotations 字段。</p><p>labels 字段需要匹配 Prometheus CRD 对象中的 ruleSelector 配置，你可以通过下面的命令来查看 Prometheus CRD 的 ruleSelector 配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl get Prometheus prometheus-kube-prometheus-prometheus -n prometheus -o j</span></span>
<span class="line"><span>{&quot;matchLabels&quot;:{&quot;release&quot;:&quot;prometheus&quot;}​}</span></span></code></pre></div><p>如果你是通过其他方式部署的 Prometheus，那么一定要确保 PrometheusRule 的 labels 和Prometheus CRD 的 ruleSelector 配置一致，否则 PrometheusRule 可能不会生效。</p><p>expr 字段用来配置告警策略，它实际上是一个断言语句，它代表当 HTTP 请求成功率小于等于 90% 的时候，就发出告警。</p><p>for 字段表示 expr 表达式会在持续多久之后发出告警，例如持续 1 分钟满足条件则发出告警。</p><p>annotations 字段用来配置发出的告警信息，除了固定的告警信息以外，这里还可以使用 Gotemplate 表达式来访问 Prometheus 内置的 labels 来实现动态的告警内容，例如</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{​{$labels.instance}​}、{​{ $labels.job }​} 和 {​{ $labels.pod }​} 等，详细信</span></span></code></pre></div><p>息你可以参考这份文档。</p><p>最后，将 PrometheusRule 应用到集群内。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl apply -f rule.yaml</span></span>
<span class="line"><span>prometheusrule.monitoring.coreos.com/http-success-rate created</span></span></code></pre></div><h3 id="检查-prometheusrule-是否生效" tabindex="-1">检查 PrometheusRule 是否生效 <a class="header-anchor" href="#检查-prometheusrule-是否生效" aria-label="Permalink to &quot;检查 PrometheusRule 是否生效&quot;">​</a></h3><p>在将 PrometheusRule CRD 应用到集群之后，接下来我们需要检查配置是否生效。你可以进入 Prometheus 控制台进行查看。</p><p>在访问控制台之前，首先需要对 Prometheus Service 进行端口转发。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl port-forward --namespace prometheus service/prometheus-kube-prometheus-</span></span></code></pre></div><p>接下来，打开浏览器，访问 <a href="http://127.0.0.1:9001" target="_blank" rel="noreferrer">http://127.0.0.1:9001</a> ，你应该能看到 Prometheus 控制台界面。点击菜单栏的 Alert 进入告警页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/4.png" alt=""></a></p><p>在 Alert 页面中，如果看到我们刚才配置的 HTTPSuccessRateDown，右侧的状态为Inactive，说明告警配置成功了，告警状态为未激活，说明是正常状态。你可以进一步展开并查看详情。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/5.png" alt=""></a></p><p>从详情页面中我们可以看到告警策略的语句和描述信息。</p><p>到这里，我们已经成功配置了 HTTP 请求成功率的告警策略。</p><h2 id="配置通知" tabindex="-1">配置通知 <a class="header-anchor" href="#配置通知" aria-label="Permalink to &quot;配置通知&quot;">​</a></h2><p>配置完告警策略之后，我们还需要配置告警通知，这样当告警生效时，Prometheus 才会将告警信息发送给我们。</p><p>Prometheus 通知的拓展性非常强，你可以将通知发送到常见的渠道里，例如企业微信、钉钉和飞书等。不过，我想先向你介绍适用性最强且配置相对简单的邮箱通知。</p><h3 id="获取邮箱-smtp-密码" tabindex="-1">获取邮箱 SMTP 密码 <a class="header-anchor" href="#获取邮箱-smtp-密码" aria-label="Permalink to &quot;获取邮箱 SMTP 密码&quot;">​</a></h3><p>要让 Prometheus 以邮件的方式发送通知，首先需要提供邮箱的 SMTP 信息，以便Prometheus 调用邮箱服务器发送邮件。</p><p>以 QQ 邮箱为例，首先我们进入设置页面，然后进入设置页面中的“账户”菜单，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/6.png" alt=""></a></p><p>然后，在“账户”菜单中找到 SMTP 设置，开启 SMTP 并生成授权码。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/7.png" alt=""></a></p><p>在生成授权码后，你将得到一串密码，我们把它复制并保存下来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/8.png" alt=""></a></p><h3 id="配置-prometheus-发信邮箱" tabindex="-1">配置 Prometheus 发信邮箱 <a class="header-anchor" href="#配置-prometheus-发信邮箱" aria-label="Permalink to &quot;配置 Prometheus 发信邮箱&quot;">​</a></h3><p>获得邮箱的 SMTP 密码之后，我们需要配置 Prometheus SMTP 发信邮箱。</p><p>你需要将下面的内容保存为 alertmanager.yaml 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> resolve_timeout: 5m</span></span>
<span class="line"><span> smtp_from: 邮箱账户</span></span>
<span class="line"><span> smtp_auth_username: 邮箱账户</span></span>
<span class="line"><span> smtp_auth_password: 授权码</span></span>
<span class="line"><span> smtp_require_tls: false</span></span>
<span class="line"><span> smtp_smarthost: &#39;smtp.qq.com:465&#39;</span></span>
<span class="line"><span>route:</span></span>
<span class="line"><span> receiver: &#39;email-alert&#39;</span></span>
<span class="line"><span> group_by: [&#39;job&#39;]</span></span>
<span class="line"><span> routes:</span></span>
<span class="line"><span> - receiver: &#39;email-alert&#39;</span></span>
<span class="line"><span>   group_wait: 50s</span></span>
<span class="line"><span>   group_interval: 5m</span></span>
<span class="line"><span>   repeat_interval: 12h</span></span>
<span class="line"><span>receivers:</span></span>
<span class="line"><span>- name: email-alert</span></span>
<span class="line"><span> email_configs:</span></span>
<span class="line"><span> - to: 接收邮箱</span></span></code></pre></div><p>注意，你需要把上面的 smtp_from、smtp_auth_username、smtp_auth_password 和email_configs.to 修改为你实际的邮箱信息。为了方便测试发送和接收邮件，你可以将smtp_from、smtp_auth_username 和 email_configs.to 字段配置都配置为同一个邮箱账户。</p><p>当告警被触发时，为了避免频繁接收到通知，我们配置了 repeat_interval 字段，它表示在 12小时之内只发送一次相同的告警信息。</p><p>此外，receivers.email_configs 字段也可以配置多个接收邮箱。</p><p>接下来，将 alertmanager.yaml 文件内容进行 Base64 编码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat alertmanager.yaml | base64</span></span>
<span class="line"><span>Z2xvYmFsOgogIHJlc29sdmVfdGltZW91dDogNW0KICBzbXRwX2Zyb206IGhhaW1pYW5ndW1hQGZveG1ha</span></span></code></pre></div><p>然后，使用 kubectl edit 命令编辑 Prometheus Secret。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl edit secret -n prometheus alertmanager-prometheus-kube-prometheus-alert</span></span>
<span class="line"><span># Please edit the object below. Lines beginning with a &#39;#&#39; will be ignored,</span></span>
<span class="line"><span># and an empty file will abort the edit. If an error occurs while saving this fil</span></span>
<span class="line"><span># reopened with the relevant failures.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>data:</span></span>
<span class="line"><span> alertmanager.yaml: Z2xvYmFsOgogIHJlc29sdmVfdGltZW91dDogNW0.... # 替换内容</span></span>
<span class="line"><span>kind: Secret</span></span></code></pre></div><p>然后将 alertmanager.yaml 字段后面的内容替换为上一步生成的 Base64 字符串，保存修改。</p><p>接下来，你还需要进入 Alertmanager 控制台检查配置是否生效。</p><p>在访问 Alertmanager 控制台之前，你需要先进行端口转发操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl port-forward svc/prometheus-kube-prometheus-alertmanager -n prometheus</span></span></code></pre></div><p>然后，使用浏览器打开 <a href="http://127.0.0.1:9093/#/status%EF%BC%8C%E6%A3%80%E6%9F%A5%E9%85%8D%E7%BD%AE%E4%BF%A1%E6%81%AF%E6%98%AF%E5%90%A6%E7%94%9F%E6%95%88%E3%80%82" target="_blank" rel="noreferrer">http://127.0.0.1:9093/#/status，检查配置信息是否生效。</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/9.png" alt=""></a></p><p>更新 Secret 可能需要几分钟后才能生效，如果你看到了刚才我们配置的邮箱信息，说明邮箱配置成功了。</p><h2 id="触发告警" tabindex="-1">触发告警 <a class="header-anchor" href="#触发告警" aria-label="Permalink to &quot;触发告警&quot;">​</a></h2><p>要触发告警，我们首先需要访问上一节课部署的示例应用，以便产生 HTTP 请求指标数据。</p><p>在示例应用中，我特意随机返回了 400 和 500 的状态码，所以 HTTP 请求成功率一定会小于90%，这样我们就可以触发告警了。</p><p>接下来，使用下面的命令来访问示例应用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ while true; do ; curl http://log-example.com/http ; echo -e &#39;\\n&#39;$(date);done</span></span></code></pre></div><p>现在，你可以进入 Grafana 控制台并打开 Ingress-Nginx Dashboard 查看 HTTP 指标信息，等待几分钟后，你将看到实时的指标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/10.png" alt=""></a></p><p>从 Dashboard 中我们可以看到 Controller Success Rate 指标，此时请求成功率小于 90%，这符合我们的预期。</p><p>接下来，使用浏览器重新打开 <a href="http://127.0.0.1:9091/alerts%EF%BC%8C%E8%BF%9B%E5%85%A5" target="_blank" rel="noreferrer">http://127.0.0.1:9091/alerts，进入</a> Prometheus Alerts 界面，你将看到我们配置的告警策略处于 Pending 状态。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/11.png" alt=""></a></p><p>这是因为 Prometheus 检测到了 HTTP 的请求成功率低于阈值，但由于告警的持续时间还没有达到预定义的时长，所以并不会发送通知。</p><p>等待 1 分钟后，告警状态从 Pending 变成了 Firing 状态，表示告警正在生效。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/12.png" alt=""></a></p><p>此时，打开邮箱，你应该能看到 Prometheus 发送的告警通知邮件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/13.png" alt=""></a></p><p>至此，我们就完成了从创建告警策略、配置邮件通知、触发告警和接收邮件告警通知的全过程。</p><h2 id="cpu-使用率告警" tabindex="-1">CPU 使用率告警 <a class="header-anchor" href="#cpu-使用率告警" aria-label="Permalink to &quot;CPU 使用率告警&quot;">​</a></h2><p>在生产环境下，除了配置 HTTP 指标告警策略以外，我还建议你配置 Pod CPU 使用率告警，这会帮助我们提前感知业务 Pod 是否正处于流量高峰，并提前做好应对措施。</p><p>你需要将下面的内容保存为 cpu-rule.yaml 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: monitoring.coreos.com/v1</span></span>
<span class="line"><span>kind: PrometheusRule</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span>   release: prometheus</span></span>
<span class="line"><span> name: cpu-usage</span></span>
<span class="line"><span> namespace: prometheus</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> groups:</span></span>
<span class="line"><span> - name: cpu.usage</span></span>
<span class="line"><span>   rules:</span></span>
<span class="line"><span>   - expr: |</span></span>
<span class="line"><span>       round( 100 * sum( rate(container_cpu_usage_seconds_total{container_name!=</span></span>
<span class="line"><span>     for: 1m</span></span>
<span class="line"><span>     alert: ContainerCPUUsage</span></span>
<span class="line"><span>     annotations:</span></span>
<span class="line"><span>       summary: &quot;Pod {​{ $labels.pod }​} CPU 使用率超过限制值 80%&quot;</span></span>
<span class="line"><span>       description: &quot;Namespace {​{ $labels.namespace }​}, Pod {​{ $labels.pod }​}, 容</span></span></code></pre></div><p>在这个告警策略中，我们用容器的 CPU 使用量 / 容器的资源 Limit 值来计算容器的 CPU 使用率，当这个值大于 80% 的时候，触发报警。</p><p>需要注意的是，要让这个告警策略生效，你需要为工作负载配置资源的 request 和 limit，在示例应用中，我已经提前配置好了。</p><p>annotations 字段和我们之前配置的 HTTP 请求成功率的通知消息有所不同，这里我们使用了Go Template 模板，并读取了内置的 labels 变量。这样，当告警被触发的时候，Prometheus会自动填充这些变量，我们可以在告警通知里面直接得到命名空间、Pod 名称、容器名以及当前 CPU 的使用率。</p><p>接下来，我们访问示例应用来触发告警策略。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ while true; do ; curl http://log-example.com/http ; echo -e &#39;\\n&#39;$(date);done</span></span></code></pre></div><p>1-2 分钟后，你可以重新打开 Prometheus Dashboard，并查看 ContainerCPUUsage 告警策略的状态，你应该能看到告警正处于 Pending 状态。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/14.png" alt=""></a></p><p>展开告警详情，会显示当前正处于 CPU 使用率告警的 Pod 信息。</p><p>等待 1 分钟后，此时 Pending 状态将变成 Firing 状态，并将收到 CPU 使用率告警的邮件通知，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/15.png" alt=""></a></p><p>至此，容器 CPU 使用率告警策略就配置完成了。</p><h3 id="其他告警策略集合" tabindex="-1">其他告警策略集合 <a class="header-anchor" href="#其他告警策略集合" aria-label="Permalink to &quot;其他告警策略集合&quot;">​</a></h3><p>要从零编写 Prometheus 告警策略并不容易，这里，我为你介绍一个社区维护的PrometheusRules 集合仓库，你可以在这个仓库中找到大部分需要在生产环境中配置的告警策略。</p><p>此外，这个集合仓库还提供了官网，你也可以在这里通过关键字来查找告警策略。</p><h2 id="其他通知方式" tabindex="-1">其他通知方式 <a class="header-anchor" href="#其他通知方式" aria-label="Permalink to &quot;其他通知方式&quot;">​</a></h2><p>除了邮件通知，我们还可以配置其他的通知方式，例如企业微信、钉钉或者飞书。不过，要使用 Prometheus 原生的扩展方式配置这些通知比较复杂，这里我介绍一种通过PrometheusAlert 项目来配置通知的方式，它配置起来相对简单，并且支持丰富的第三方通知。</p><h3 id="安装-prometheusalert" tabindex="-1">安装 PrometheusAlert <a class="header-anchor" href="#安装-prometheusalert" aria-label="Permalink to &quot;安装 PrometheusAlert&quot;">​</a></h3><p>首先，我们需要安装 PrometheusAlert 项目，你可以使用下面的命令来安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl create ns monitoring</span></span>
<span class="line"><span>$ kubectl apply -n monitoring -f https://ghproxy.com/https://raw.githubuserconten</span></span>
<span class="line"><span>configmap/prometheus-alert-center-conf created</span></span>
<span class="line"><span>deployment.apps/prometheus-alert-center created</span></span>
<span class="line"><span>service/prometheus-alert-center created</span></span></code></pre></div><p>然后，等待工作负载就绪。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl wait --for=condition=Ready pods --all -n monitoring</span></span>
<span class="line"><span>pod/prometheus-alert-center-75b7b6465-26zvd condition met</span></span></code></pre></div><h3 id="配置-prometheusalert" tabindex="-1">配置 PrometheusAlert <a class="header-anchor" href="#配置-prometheusalert" aria-label="Permalink to &quot;配置 PrometheusAlert&quot;">​</a></h3><p>安装完成后，PrometheusAlert 会默认开启钉钉和企业微信通知的开关，但并没有开启飞书开关。这里我以飞书通知为例介绍一下配置方法。</p><p>首先我们需要启用飞书通知开关。要启用飞书通知，你需要编辑 PrometheusAlert 存储配置的configmap。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl edit configmap prometheus-alert-center-conf -n monitoring</span></span>
<span class="line"><span>#是否开启飞书告警通道,可同时开始多个通道0为关闭,1为开启</span></span>
<span class="line"><span>open-feishu=0</span></span></code></pre></div><p>找到 open-feishu 配置项，并将 0 修改为 1，保存配置。</p><p>然后，要让配置立即生效，你可以删除旧的 Pod。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pod </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prometheus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">alert</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">center </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n monitoring</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pod </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prometheus-alert-center-75b7b6465-26zvd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deleted</span></span></code></pre></div><p>这样，飞书通知的开关也就开启了。</p><h3 id="创建飞书机器人" tabindex="-1">创建飞书机器人 <a class="header-anchor" href="#创建飞书机器人" aria-label="Permalink to &quot;创建飞书机器人&quot;">​</a></h3><p>下一步，我们需要创建飞书机器人。首先，你需要创建一个群聊，然后点击群聊“设置”，选择“群机器人”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/16.png" alt=""></a></p><p>在弹出的界面中，选择“添加机器人”，然后选择“自定义机器人”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/17.png" alt=""></a></p><p>接下来，点击“添加”完成机器人创建过程，此时你将得到一个 webhook 地址，例如：<a href="https://open.feishu.cn/open-apis/bot/v2/hook/xxxx-xxx%EF%BC%8C%E5%B0%86%E5%AE%83%E5%A4%8D%E5%88%B6%E4%B8%8B%E6%9D%A5%E5%A4%87%E7%94%A8%E3%80%82" target="_blank" rel="noreferrer">https://open.feishu.cn/open-apis/bot/v2/hook/xxxx-xxx，将它复制下来备用。</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/18.png" alt=""></a></p><h3 id="配置-alertmanager" tabindex="-1">配置 Alertmanager <a class="header-anchor" href="#配置-alertmanager" aria-label="Permalink to &quot;配置 Alertmanager&quot;">​</a></h3><p>接下来，我们还需要配置 Alertmanager，让所有通知都转发到 PrometheusAlert 去处理。</p><p>将下面的内容保存为 prometheusAlert.yaml 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> resolve_timeout: 5m</span></span>
<span class="line"><span>route:</span></span>
<span class="line"><span> group_by: [&#39;instance&#39;]</span></span>
<span class="line"><span> group_wait: 10m</span></span>
<span class="line"><span> group_interval: 1m</span></span>
<span class="line"><span> repeat_interval: 12h</span></span>
<span class="line"><span> receiver: &#39;web.hook.prometheusalert&#39;</span></span>
<span class="line"><span>receivers:</span></span>
<span class="line"><span>- name: &#39;web.hook.prometheusalert&#39;</span></span>
<span class="line"><span> webhook_configs:</span></span>
<span class="line"><span>- url: &#39;http://prometheus-alert-center.monitoring:8080/prometheusalert?type=fs&amp;</span></span></code></pre></div><p>从这段配置内容中我们会发现，这里本质上是使用了 Alertmanager 的 webhook 功能，将所有告警以 HTTP 的方式发送到了 PrometheusAlert，并由它来发送通知。</p><p>请注意，你需要将 url 字段中的 fsurl 参数替换为之前创建的飞书 webhook 地址。</p><p>当然你也可以使用其他的通知方式，例如企业微信或者钉钉，只需要构造不同的 url 参数就可以了，你可以参考这个链接。</p><p>然后，将该文件内容进行 base64 编码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat prometheusAlert.yaml| base64</span></span>
<span class="line"><span>Z2xvYmFsOgogIHJlc29sdmVfdGltZW91dDogNW0Kcm91dGU6CiAgZ3JvdXBfYnk6IFsnaW5zdGFuY2UnX</span></span></code></pre></div><p>接下来，编辑 Alertmanager 的 Secret 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl edit secret -n prometheus alertmanager-prometheus-kube-prometheus-alert</span></span>
<span class="line"><span># Please edit the object below. Lines beginning with a &#39;#&#39; will be ignored,</span></span>
<span class="line"><span># and an empty file will abort the edit. If an error occurs while saving this fil</span></span>
<span class="line"><span># reopened with the relevant failures.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>data:</span></span>
<span class="line"><span> alertmanager.yaml: Z2xvYmFsOgogIHJlc29sdmVfdGltZW91dDogNW0.... # 替换内容</span></span>
<span class="line"><span>kind: Secret</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>将 alertmanager.yaml 字段后面的内容替换为上一步生成的 Base64 字符串，保存修改。</p><p>为了让配置立即生效，你可以删除旧的 Alertmanager Pod。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pod </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kubernetes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">io/name=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">alertmanager </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n prometheus</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pod </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alertmanager-prometheus-kube-prometheus-alertmanager-0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deleted</span></span></code></pre></div><h3 id="触发告警-1" tabindex="-1">触发告警 <a class="header-anchor" href="#触发告警-1" aria-label="Permalink to &quot;触发告警&quot;">​</a></h3><p>接下来，仍然使用下面的命令来访问示例应用，以便触发告警。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ while true; do ; curl http://log-example.com/http ; echo -e &#39;\\n&#39;$(date);done</span></span></code></pre></div><p>等待几分钟后，你将在飞书收到告警通知。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/33/19.png" alt=""></a></p><p>到这里，我们就完成了使用 PrometheusAlert 发送告警通知的全过程。</p><p>PrometheusAlert 支持的通知类型有非常多，除了常见的 IM，还支持短信和电话通知，你可以参考这个文档进行配置。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们学习了如何创建 Prometheus 告警策略，并通过配置邮件通知来接收告警。</p><p>对于新手来说，编写 PromQL 并不是一件容易的事，所以我教你了一个小技巧，也就是通过查看 Dashboard 的指标来获得查询语句，并将它配置成 PrometheusRule 对象，这样就完成了指标告警配置。通过这种方式，理论上你可以对任何 Dashboard 中已有的指标配置告警策略。</p><p>在配置通知方面，我首先介绍了通用性最强也最简单的邮箱配置方法，不同的邮箱配置稍有差异，不过你只需要找到邮箱的 SMTP 服务器、账号和密码也就可以了。此外，我还介绍了PrometheusAlert 项目，通过它你可以配置丰富的通知渠道，配置过程也相对比较简单。</p><p>最后，我还提到了社区维护的 PrometheusRules 集合仓库，如果你想找到更多现成的告警策略并深入学习 PromQL，那么从这里开始是一个不错的起点。</p><p>到这里，GitOps 的可观测性专题也就全部结束了。通过为业务系统配置日志、监控和告警策略，我相信你已经能全方位掌握业务的健康状态，也具备提前发现问题和解决业务隐患的能力了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留一道思考题吧。</p><p>你认为在生产环境下，我们还需要对哪些指标配置告警呢？说说你的理解。</p><p>欢迎你给我留言交流讨论，你也可以把这节课分享给更多的朋友一起阅读。我们下节课见。</p>`,161)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
